import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

scale_min_source = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void scale_min_kernel(const float* x, float* out, float scale_factor, int N, int C, int H, int W) {
    int batch_idx = blockIdx.x;
    int h_idx = blockIdx.y * blockDim.y + threadIdx.y;
    int w_idx = blockIdx.z * blockDim.z + threadIdx.z;
    if (h_idx < H && w_idx < W) {
        float val = x[((batch_idx * C) * H + h_idx) * W + w_idx] * scale_factor;
        for (int c = 1; c < C; c++) {
            float temp = x[(((batch_idx * C) + c) * H + h_idx) * W + w_idx] * scale_factor;
            if (temp < val) {
                val = temp;
            }
        }
        out[((batch_idx * 1) * H + h_idx) * W + w_idx] = val;
    }
}

torch::Tensor scale_min_cuda(torch::Tensor x, float scale_factor) {
    const auto N = x.size(0);
    const auto C = x.size(1);
    const auto H = x.size(2);
    const auto W = x.size(3);

    auto out = torch::zeros({N, 1, H, W}, x.options());

    dim3 blockDim(1, 16, 16);
    dim3 gridDim(N, (H + blockDim.y - 1) / blockDim.y, (W + blockDim.z - 1) / blockDim.z);

    scale_min_kernel<<<gridDim, blockDim>>>(x.data_ptr<float>(), out.data_ptr<float>(), scale_factor, N, C, H, W);

    return out;
}
""";

scale_min_cpp_source = r"""
torch::Tensor scale_min_cuda(torch::Tensor x, float scale_factor);
""";

scale_min_module = load_inline(
    name="scale_min",
    cpp_sources=scale_min_cpp_source,
    cuda_sources=scale_min_source,
    functions=["scale_min_cuda"],
    verbose=False
)

class ModelNew(nn.Module):
    def __init__(self, in_channels, out_channels, kernel_size, scale_factor):
        super(ModelNew, self).__init__()
        self.conv = nn.Conv2d(in_channels, out_channels, kernel_size)
        self.scale_factor = scale_factor

    def forward(self, x):
        x = self.conv(x)
        x = scale_min_module.scale_min_cuda(x, self.scale_factor)
        return x

